function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'ExamRoom' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with ExamRoom and its seat count n.';
  const n = args[0][0];
  if (!Number.isInteger(n) || n < 1 || n > 1000000000) return 'n is between 1 and 10^9.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to seat and leave.';
  // Replay the seating rule so that each leave can be checked against the occupied seats.
  const seats = [];
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] === 'seat') {
      if (args[i].length !== 0) return 'seat takes no arguments.';
      if (seats.length === n) return 'seat is only called while an empty seat exists.';
      let best = 0, bestDistance = seats.length ? seats[0] : Infinity, at = 0;
      for (let j = 1; j < seats.length; j++) {
        const d = Math.floor((seats[j] - seats[j - 1]) / 2);
        if (d > bestDistance) { bestDistance = d; best = seats[j - 1] + d; at = j; }
      }
      if (seats.length && n - 1 - seats[seats.length - 1] > bestDistance) { best = n - 1; at = seats.length; }
      seats.splice(at, 0, best);
    } else if (operations[i] === 'leave') {
      if (args[i].length !== 1 || !Number.isInteger(args[i][0])) return 'leave takes one seat number.';
      const index = seats.indexOf(args[i][0]);
      if (index < 0) return `leave(${args[i][0]}) needs a student in that seat.`;
      seats.splice(index, 1);
    } else return 'Only seat and leave can follow the constructor.';
  }
  return null;
}

