class ExamRoom {
  constructor(n) {
    this.n = n;
    this.seats = [];
  }

  seat() {
    const seats = this.seats;
    if (seats.length === 0) {
      seats.push(0);
      return 0;
    }
    let best = 0;
    let bestDistance = seats[0];
    let insertAt = 0;
    for (let i = 1; i < seats.length; i++) {
      const distance = Math.floor((seats[i] - seats[i - 1]) / 2);
      if (distance > bestDistance) {
        bestDistance = distance;
        best = seats[i - 1] + distance;
        insertAt = i;
      }
    }
    const last = seats[seats.length - 1];
    if (this.n - 1 - last > bestDistance) {
      best = this.n - 1;
      insertAt = seats.length;
    }
    seats.splice(insertAt, 0, best);
    return best;
  }

  leave(p) {
    const seats = this.seats;
    let left = 0;
    let right = seats.length - 1;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (seats[mid] < p) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    seats.splice(left, 1);
  }
}

