class ExamRoom {
  constructor(n) {
    this.n = n;
    this.taken = new Set();
  }
  seat() {
    let candidates;
    if (this.n <= 2000) {
      candidates = Array.from({ length: this.n }, (_, i) => i);
    } else {
      // In a huge row the best seat is an end or the middle of two taken seats.
      const set = new Set([0, this.n - 1]);
      const list = [...this.taken];
      for (const a of list) for (const b of list) set.add(Math.floor((a + b) / 2));
      candidates = [...set];
    }
    let choice = -1, far = -1;
    for (const c of candidates) {
      if (this.taken.has(c)) continue;
      let near = Infinity;
      for (const t of this.taken) near = Math.min(near, Math.abs(t - c));
      if (near > far || (near === far && c < choice)) { far = near; choice = c; }
    }
    this.taken.add(choice);
    return choice;
  }
  leave(p) {
    this.taken.delete(p);
  }
}

