function generate(rand, size) {
  const r = rand();
  const n = size === 'large'
    ? (r < 0.5 ? 1000000000 - Math.floor(rand() * 1000) : 200 + Math.floor(rand() * 5000))
    : (r < 0.15 ? 1 + Math.floor(rand() * 1000000000) : 1 + Math.floor(rand() * 12));
  const calls = size === 'large' ? 499 : 1 + Math.floor(rand() * 14);
  const leaveRate = rand() * 0.45;
  const operations = ['ExamRoom'];
  const args = [[n]];
  const seats = [];
  for (let c = 0; c < calls; c++) {
    const canSeat = seats.length < n;
    if (seats.length > 0 && (!canSeat || rand() < leaveRate)) {
      const p = seats[Math.floor(rand() * seats.length)];
      seats.splice(seats.indexOf(p), 1);
      operations.push('leave');
      args.push([p]);
      continue;
    }
    // Simulate the seating rule to know which seats a later leave may name.
    let best = 0, bestDistance = seats.length ? seats[0] : Infinity, at = 0;
    for (let i = 1; i < seats.length; i++) {
      const d = Math.floor((seats[i] - seats[i - 1]) / 2);
      if (d > bestDistance) { bestDistance = d; best = seats[i - 1] + d; at = i; }
    }
    if (seats.length && n - 1 - seats[seats.length - 1] > bestDistance) { best = n - 1; at = seats.length; }
    seats.splice(at, 0, best);
    operations.push('seat');
    args.push([]);
  }
  return [operations, args];
}
